// appsettings.json
{
  "Cors": {
    "AllowedOrigins": [
      "https://localhost:3000",
      "https://staging.example.com"
    ]
  }
}

// Program.cs
var allowedOrigins = builder.Configuration.GetSection("Cors:AllowedOrigins").Get<string[]>() ?? [];
options.AddPolicy("Production", policy =>
{
    policy.WithOrigins(allowedOrigins)
          .AllowAnyHeader()
          .AllowAnyMethod();
});
